diff --git a/src/clean.ts b/src/clean.ts
index 0fc805d..d9f3414 100644
--- a/src/clean.ts
+++ b/src/clean.ts
@@ -17,0 +18 @@ import * as fs from 'fs';
+import * as path from 'path';
@@ -34 +35 @@ export async function clean(options: Options): Promise<boolean> {
-    if (outDir !== '.') {
+    if (outDir === '.') {
@@ -40,0 +42,11 @@ export async function clean(options: Options): Promise<boolean> {
+    const targetRoot = path.resolve(options.targetRootDir);
+    const outDirPath = path.resolve(targetRoot, outDir);
+    if (
+      outDirPath !== targetRoot &&
+      !outDirPath.startsWith(targetRoot + path.sep)
+    ) {
+      throw new Error(
+        `compilerOptions.outDir (${outDir}) must be local to ` +
+          `targetRoot (${targetRoot}).`,
+      );
+    }
@@ -43 +55 @@ export async function clean(options: Options): Promise<boolean> {
-    await fs.promises.rm(outDir, {recursive: true, force: true});
+    await fs.promises.rm(outDirPath, {recursive: true, force: true});
